// Card icon colors use Wisdom · sequence G (Pen frame zdKDH), excluding gray and yellow.
// Store colors with cards so adding a suggestion keeps the existing palette assignments.
let mountSequence = 0;

/** Mount the Suggestions cards without changing the surrounding tabs. */
export function mountAgentSuggestions(panel, { onPreview }) {
  if (!panel?.ownerDocument || typeof onPreview !== 'function') {
    throw new TypeError('A Suggestions panel and preview callback are required.');
  }
  const document = panel.ownerDocument;
  const instance = ++mountSequence;
  let artworkSequence = 0;

  function element(tag, className, text) {
    const node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined) node.textContent = text;
    return node;
  }

  function artwork(markup) {
    // Only the static exported icon constants above enter this template.
    // All visible copy is assigned with textContent.
    const template = document.createElement('template');
    template.innerHTML = markup;
    const icon = template.content.firstElementChild;
    const prefix = `suggestions-${instance}-${++artworkSequence}-`;
    const ids = new Map([...icon.querySelectorAll('[id]')].map((node) => [node.id, `${prefix}${node.id}`]));
    for (const node of [icon, ...icon.querySelectorAll('*')]) {
      for (const attribute of [...node.attributes]) {
        let value = attribute.value;
        if (attribute.name === 'id' && ids.has(value)) value = ids.get(value);
        else for (const [id, replacement] of ids) {
          value = value.replaceAll(`url(#${id})`, `url(#${replacement})`);
          if (value === `#${id}`) value = `#${replacement}`;
        }
        if (value !== attribute.value) node.setAttribute(attribute.name, value);
      }
    }
    icon.classList.add('agent-suggestions-artwork');
    icon.style.display = 'block';
    icon.setAttribute('aria-hidden', 'true');
    return icon;
  }

  function mainIcon(asset, accent) {
    const icon = element('span', 'agent-suggestions-artwork agent-suggestions-main-icon');
    const source = `url("${new URL(asset, import.meta.url).href}")`;
    icon.style.setProperty('--suggestion-icon-accent', accent);
    icon.style.maskImage = source;
    icon.style.webkitMaskImage = source;
    icon.setAttribute('aria-hidden', 'true');
    return icon;
  }

  function previewButton(item, className, text) {
    const button = element('button', className, text);
    button.type = 'button';
    button.setAttribute('aria-label', `Use ${item.title}`);
    button.addEventListener('click', () => onPreview({ title: item.title, description: item.description }));
    return button;
  }

  function cardsView() {
    const gallery = element('div', 'agent-suggestions-gallery');
    for (const group of CARD_GROUPS) {
      const section = element('section', 'agent-suggestions-group');
      const heading = element('h2', 'agent-suggestions-group-heading', group.title);
      const grid = element('div', 'agent-suggestions-card-grid');
      section.setAttribute('aria-label', group.title);
      for (const item of group.cards) {
        const card = element('article', 'agent-suggestions-card');
        const header = element('div', 'agent-suggestions-card-header');
        header.append(mainIcon(item.icon, item.iconColor), previewButton(item, 'agent-suggestions-use', 'Use'));
        const copy = element('div', 'agent-suggestions-card-copy');
        copy.append(element('h3', 'agent-suggestions-card-title', item.title), element('p', 'agent-suggestions-card-description', item.description));
        const meta = element('div', 'agent-suggestions-card-meta');
        const cadence = element('span', 'agent-suggestions-meta-item');
        cadence.append(artwork(item.cadenceIcon), element('span', '', item.cadence));
        const delivery = element('span', 'agent-suggestions-meta-item');
        delivery.append(artwork(item.deliveryIcon), element('span', '', item.delivery));
        meta.append(cadence, artwork(item.arrowIcon), delivery);
        card.append(header, copy, meta);
        grid.append(card);
      }
      section.append(heading, grid);
      gallery.append(section);
    }
    return gallery;
  }

  panel.replaceChildren(cardsView());
}
